    colors = {v for row in grid for v in row}
    foreground = min(colors) if len(colors) == 2 else next(iter(colors - {0}))

    row_spans = []
    for row in grid:
        cols = [c for c, v in enumerate(row) if v == foreground]
        row_spans.append((min(cols), max(cols)) if len(cols) >= 2 else None)

    col_spans = []
