def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1

    background = max(counts, key=counts.get)
    marker = next(value for value in counts if value != background)
    out = [row[:] for row in grid]

    # Fill the gaps between consecutive markers in each row.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] != marker:
                    out[r][c] = 3

    # Fill the gaps between consecutive markers in each column.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] != marker:
                    out[r][c] = 3

    return out
